        {'type': 'sort', 'target_column': 1, 'numeric': False},
        {'type': 'remove_columns', 'target_columns': [0, 3]},
    ],
    'mapping': [
        {'type': 'list_identifiers', 'columns': [1]},
        {'type': 'paired_identifier', 'columns': [2]},
    ]
}

inputs = {
    'input': {'src': 'hdca', 'id': '71cb97f2d8427870'},
    'rules': rules,
}

