import requests, json

API_KEY = '$GALAXY_API_KEY'
HISTORY = 'bbd44e69cb8906b5077a8e0c9ba53bc1'

# Full transform: parse identifier, sort by sample, create paired
rules = {
    'rules': [
        {'type': 'add_column_metadata', 'value': 'identifier0'},
        {'type': 'add_column_regex', 'target_column': 0, 'expression': '(SRR\d+):(forward|reverse)', 'group_count': 2},
    ],
    'mapping': [
        {'type': 'list_identifiers', 'columns': [1]},
        {'type': 'paired_identifier', 'columns': [2]},
    ]
}

inputs = {
    'input': {'src': 'hdca', 'id': '71cb97f2d8427870'},
    'rules': rules,
}

payload = {
    'history_id': HISTORY,
    'tool_id': '__APPLY_RULES__',
    'inputs': json.dumps(inputs),
}

r = requests.post(
    'https://usegalaxy.org/api/tools',
    headers={'x-api-key': API_KEY},
    data=payload
)
print(f'Status: {r.status_code}')
result = r.json()
if r.status_code == 200:
    print(f'Jobs: {len(result.get(\"jobs\",[]))}')
    for j in result.get('jobs', []):
        print(f'  Job: {j[\"id\"]} state={j[\"state\"]}')
    for oc in result.get('output_collections', []):
        cid = oc['id']
        print(f'Output collection: {cid}')
        r2 = requests.get(
            f'https://usegalaxy.org/api/histories/{HISTORY}/contents/dataset_collections/{cid}',
            headers={'x-api-key': API_KEY}
        )
        c = r2.json()
        print(f'  Type: {c[\"collection_type\"]}, Elements: {c[\"element_count\"]}')
        for e in c.get('elements', [])[:3]:
            print(f'  - {e[\"element_identifier\"]} ({e[\"element_type\"]})')
            if e['element_type'] == 'dataset_collection':
                for se in e.get('object', {}).get('elements', []):
